VALUES
('3173ad24bc344c0fbd1177f7e9ecb63d', 'EPA_STANDARD_V1', 'Neurology', 'Patient Interaction Skills', 'Detailed step', 'Beginner', 'Patient Interaction Skills', 'Create test for medical learner to test the patient interaction skill', 'Create test for medical learner to test the patient interaction skill', 10, 30, 30, 3, '["MultipleChoice"]', TRUE);
INSERT INTO latee.assessments (assessment_id, module_id, specialty, topic, subtopic, difficulty_level, title, descriptions, goal, num_questions, time_limit_minutes, passing_score_percentage, max_attempts, allowed_question_types, is_active, created_at, updated_at) VALUES ('036954762944430699ca153fb1b0f87e', 'EPA_STANDARD_V1', 'Neurology', 'Abdominal pathology', 'Appendicitis', 'Intermediate', 'Abdominal pathology', 'Important procedures in diagnosing abdominal pathology, especially appendicitis', 'Creating a roadmap to learn and understand the key points in the diagnostic procedure for abdominal pathology', 5, 15, 50.00, 3, '["MultipleChoice"]', 1, '2026-05-21 16:08:31', '2026-05-21 16:09:09');
INSERT INTO latee.question (id, assessment_id, question, question_option, question_type, cognitive_level, explanation, points, created_at, updated_at) VALUES ('0009452c8a6d4b05bb2f62d4253afa6c', '3173ad24bc344c0fbd1177f7e9ecb63d', 'A 55-year-old female presents to the clinic with acute onset vertigo, nausea, and nystagmus. An MRI brain confirms a small cerebellar infarct. Her vital signs are stable (BP 130/80 mmHg, HR 70 bpm, RR 14 bpm, Temp 36.8Â°C). She is very anxious about having another stroke and asks, \'What can I do to make sure this never happens again?\'', '[{"id": "A", "text": "Explain the modifiable risk factors for stroke (e.g., hypertension, hyperlipidemia, diabetes, smoking), discuss the importance of medication adherence (e.g., antiplatelets, statins), and collaboratively set realistic lifestyle modification goals, while acknowledging her anxiety.", "isCorrect": true}, {"id": "B", "text": "Reassure her that since this was a small stroke, the chances of another one are very low if she takes her prescribed medication.", "isCorrect": false}, {"id": "C", "text": "Provide her with a detailed list of all possible stroke risk factors and tell her to avoid them, without prioritizing or personalizing the advice.", "isCorrect": false}, {"id": "D", "text": "Focus primarily on the importance of taking her antiplatelet medication, as that is the most critical intervention.", "isCorrect": false}]', 'MultipleChoice', 'Apply', 'Option A is the most comprehensive and patient-centered approach. It addresses her anxiety, provides actionable information about modifiable risk factors, emphasizes medication adherence, and promotes shared decision-making by setting collaborative goals. This empowers the patient while providing realistic expectations. Option B provides false reassurance and downplays the importance of comprehensive secondary prevention. Option C is overwhelming and unhelpful without personalization and prioritization. Option D, while important, is incomplete and neglects other crucial aspects of secondary stroke prevention and patient education.', 1.00, '2026-05-21 15:18:20', '2026-05-21 15:18:20');
INSERT INTO latee.question (id, assessment_id, question, question_option, question_type, cognitive_level, explanation, points, created_at, updated_at) VALUES ('06d5501d944144b2a73ce850f7c0f9c7', '3173ad24bc344c0fbd1177f7e9ecb63d', 'A 72-year-old male with a 10-year history of Parkinson\'s disease is experiencing significant motor fluctuations and troublesome dyskinesias despite optimal medical management with levodopa and other adjunctive therapies. His neurologist has suggested Deep Brain Stimulation (DBS) as a potential option. The patient expresses significant anxiety about brain surgery, stating, \'I\'m scared of something going wrong in my brain.\'', '[{"id": "A", "text": "Acknowledge his fears, explain the general principles of DBS, discuss the potential benefits in managing his specific symptoms, and transparently review the common risks and potential complications, emphasizing the multidisciplinary team approach.", "isCorrect": true}, {"id": "B", "text": "Tell him that DBS is a very safe procedure with minimal risks and that his quality of life will significantly improve.", "isCorrect": false}, {"id": "C", "text": "Focus solely on the positive outcomes and success stories of DBS to alleviate his anxiety.", "isCorrect": false}, {"id": "D", "text": "Advise him that if he doesn\'t undergo DBS, his symptoms will continue to worsen, implying it\'s his only viable option.", "isCorrect": false}]', 'MultipleChoice', 'Apply', 'Option A is the most appropriate approach. It validates the patient\'s fears, provides a balanced and transparent discussion of both benefits and risks, and highlights the supportive multidisciplinary team. This fosters trust and allows for informed decision-making. Option B provides false reassurance and downplays real surgical risks. Option C is biased and does not allow for informed consent. Option D uses fear tactics and is coercive, which is unethical and inappropriate.', 1.00, '2026-05-21 15:18:20', '2026-05-21 15:18:20');
INSERT INTO latee.question (id, assessment_id, question, question_option, question_type, cognitive_level, explanation, points, created_at, updated_at) VALUES ('1f47059575c94cabae9b0fb0776fabf1', '3173ad24bc344c0fbd1177f7e9ecb63d', 'A 35-year-old female is newly diagnosed with Relapsing-Remitting Multiple Sclerosis (RRMS) after experiencing an episode of optic neuritis. Her MRI brain shows multiple T2 hyperintense lesions in the periventricular and juxtacortical regions, some with gadolinium enhancement. She is visibly overwhelmed and asks, \'What does this mean for my future? Will I end up in a wheelchair? What are my treatment options?\'', '[{"id": "A", "text": "Start by validating her feelings, explaining MS in simple terms, discussing the relapsing-remitting course, and then briefly outlining the goals of disease-modifying therapies (DMTs) before scheduling a follow-up for a more detailed discussion.", "isCorrect": true}, {"id": "B", "text": "Immediately launch into a detailed explanation of all available disease-modifying therapies, including their mechanisms of action, side effects, and administration routes.", "isCorrect": false}, {"id": "C", "text": "Reassure her that most people with MS live normal lives and that she shouldn\'t worry too much about future disability.", "isCorrect": false}, {"id": "D", "text": "Provide her with a stack of brochures and websites about MS and tell her to come back with specific questions after she\'s had a chance to read them.", "isCorrect": false}]', 'MultipleChoice', 'Apply', 'Option A is the most appropriate initial step. It prioritizes empathy and addresses her immediate emotional state. It then provides a foundational understanding of MS and its course, setting realistic expectations without overwhelming her. Briefly mentioning DMTs and scheduling a follow-up allows for a more comprehensive discussion once she has processed the initial diagnosis. Option B is overwhelming for a newly diagnosed patient. Option C provides false reassurance and minimizes her valid concerns. Option D is dismissive and lacks direct patient engagement and support.', 1.00, '2026-05-21 15:18:20', '2026-05-21 15:18:20');
INSERT INTO latee.question (id, assessment_id, question, question_option, question_type, cognitive_level, explanation, points, created_at, updated_at) VALUES ('21a77bff2e854cfdbf7ca7707f6f6b3f', '3173ad24bc344c0fbd1177f7e9ecb63d', 'A 55-year-old male, diagnosed with Amyotrophic Lateral Sclerosis (ALS) 6 months ago, is now experiencing significant bulbar weakness, leading to difficulty swallowing and weight loss. He is visibly distressed and tearful as he asks about the possibility of a feeding tube (percutaneous endoscopic gastrostomy - PEG).', '[{"id": "A", "text": "Acknowledge his distress and fears, validate his emotions, and then gently explain the purpose of a PEG tube, its potential benefits (nutrition, hydration, medication delivery), and the associated risks, allowing ample time for questions and emotional processing.", "isCorrect": true}, {"id": "B", "text": "Immediately present the PEG tube as a necessary intervention to prevent further weight loss and aspiration, focusing on the technical aspects of the procedure.", "isCorrect": false}, {"id": "C", "text": "Tell him that many ALS patients choose PEG tubes and that it\'s a routine procedure, trying to minimize his concerns.", "isCorrect": false}, {"id": "D", "text": "Suggest he discuss it with his family first before you provide any detailed information.", "isCorrect": false}]', 'MultipleChoice', 'Apply', 'Option A is the most empathetic and appropriate way to initiate this difficult conversation. It prioritizes acknowledging the patient\'s emotional state before delving into medical details, which is crucial when discussing life-altering decisions in the context of a progressive neurodegenerative disease. It then provides balanced information about benefits and risks, allowing for informed decision-making. Option B is too direct and lacks empathy for his emotional state. Option C minimizes his valid fears and concerns about a significant medical intervention. Option D defers responsibility and may make the patient feel unsupported in a vulnerable moment.', 1.00, '2026-05-21 15:18:20', '2026-05-21 15:18:20');
INSERT INTO latee.question (id, assessment_id, question, question_option, question_type, cognitive_level, explanation, points, created_at, updated_at) VALUES ('33034ae68c50463287dea2d79b4d20f7', '036954762944430699ca153fb1b0f87e', 'A 28-year-old male undergoes an uncomplicated laparoscopic appendectomy for acute non-perforated appendicitis. On post-operative day 2, he develops acute confusion, disorientation, and visual hallucinations. His vital signs are stable (BP 125/75 mmHg, HR 72 bpm, RR 14 bpm, Temp 37.2°C). Labs show a WBC count of 9,500/µL (down from pre-op), normal electrolytes, and normal renal/hepatic function. He is currently receiving IV fluids, acetaminophen, and a patient-controlled analgesia (PCA) pump with hydromorphone. His family reports no prior psychiatric history. What is the most appropriate *initial* step in the evaluation and management of this patient\'s acute post-operative neurological change?', '[{"id": "A", "text": "Review and adjust current medication regimen, particularly analgesics and sedatives.", "isCorrect": true}, {"id": "B", "text": "Order an urgent head CT scan to rule out intracranial pathology.", "isCorrect": false}, {"id": "C", "text": "Initiate broad-spectrum antibiotics empirically for post-operative sepsis.", "isCorrect": false}, {"id": "D", "text": "Consult psychiatry for acute psychosis.", "isCorrect": false}]', 'MultipleChoice', 'Apply', 'The patient is experiencing acute post-operative delirium, a common neurological complication after surgery. Given his stable vital signs, normal labs, and lack of fever, sepsis or a new intracranial event are less likely as the immediate primary cause. A common and reversible cause of post-operative delirium is medication side effects, particularly from opioids (like hydromorphone in a PCA) and other sedatives. Therefore, the most appropriate *initial* step is to review and adjust his current medication regimen, aiming to minimize deliriogenic drugs. While a head CT might be considered if other causes are ruled out or if focal neurological signs develop, it\'s not the immediate first step. Empiric antibiotics are not indicated without signs of infection. Psychiatry consultation is appropriate if medical causes are ruled out or for behavioral management, but not as the initial diagnostic step. This approach aligns with neurology guidelines for delirium management, which emphasizes identifying and treating reversible causes.', 1.00, '2026-05-21 16:09:08', '2026-05-21 16:09:08');
INSERT INTO latee.question (id, assessment_id, question, question_option, question_type, cognitive_level, explanation, points, created_at, updated_at) VALUES ('45b3a6e3566647a49e552cecf7fd5455', '3173ad24bc344c0fbd1177f7e9ecb63d', 'A 60-year-old female presents with progressive memory loss and cognitive decline over the past 2 years. Neuropsychological testing confirms moderate cognitive impairment consistent with a neurodegenerative process. Her neurological exam is otherwise normal. Her family, present during the consultation, asks about genetic testing for Alzheimer\'s disease, as her mother also had dementia.', '[{"id": "A", "text": "Discuss the limited utility of routine genetic testing (e.g., APOE) for late-onset Alzheimer\'s in guiding treatment or prognosis, explain the potential psychological and social implications, and offer referral for genetic counseling if they still wish to pursue it.", "isCorrect": true}, {"id": "B", "text": "Order APOE genotyping immediately, explaining that it will confirm the diagnosis of Alzheimer\'s disease.", "isCorrect": false}, {"id": "C", "text": "Tell the family that genetic testing is only for early-onset Alzheimer\'s and is not relevant in her case.", "isCorrect": false}, {"id": "D", "text": "Advise against genetic testing, stating that there is no cure for Alzheimer\'s disease, so the information would not be helpful.", "isCorrect": false}]', 'MultipleChoice', 'Apply', 'Option A is the most appropriate and ethical approach. It provides accurate information about the current role of genetic testing (like APOE) in late-onset Alzheimer\'s, which is primarily for research and not typically for routine diagnosis or prognosis. It also addresses the significant psychosocial implications of such testing and offers a referral to a specialist (genetic counselor) for a more in-depth discussion, respecting patient autonomy. Option B is incorrect; APOE genotyping is not diagnostic for Alzheimer\'s and has limited clinical utility in late-onset disease. Option C is partially incorrect; while more relevant for early-onset, it\'s not entirely irrelevant for discussion in late-onset, but its utility is limited. Option D is dismissive and fails to acknowledge the patient\'s and family\'s right to information and shared decision-making, even if there\'s no cure.', 1.00, '2026-05-21 15:18:20', '2026-05-21 15:18:20');
INSERT INTO latee.question (id, assessment_id, question, question_option, question_type, cognitive_level, explanation, points, created_at, updated_at) VALUES ('5e0bfaa9ca98456b8e9092f622f903d4', '3173ad24bc344c0fbd1177f7e9ecb63d', 'An 80-year-old male with advanced Alzheimer\'s disease is admitted to the hospital with recurrent aspiration pneumonia. He is non-verbal and unable to participate in decision-making. His family is present, with one daughter advocating for aggressive treatment including intubation and a feeding tube, while another son believes comfort care is more appropriate. The patient has no documented advanced directives.', '[{"id": "A", "text": "Facilitate a family meeting to explore the patient\'s values and preferences based on their knowledge of him, discuss the prognosis of advanced Alzheimer\'s and recurrent aspiration pneumonia, and explain the potential benefits and burdens of aggressive interventions versus comfort care.", "isCorrect": true}, {"id": "B", "text": "Proceed with aggressive interventions as requested by the daughter, as she is the most vocal advocate for her father.", "isCorrect": false}, {"id": "C", "text": "Inform the family that since there are no advanced directives, the medical team will make decisions based on what they deem medically appropriate.", "isCorrect": false}, {"id": "D", "text": "Suggest the family seek legal counsel to appoint a medical power of attorney to resolve the disagreement.", "isCorrect": false}]', 'MultipleChoice', 'Apply', 'Option A is the most appropriate initial step. It promotes shared decision-making by involving the family in a structured discussion, acknowledging their differing views, and providing essential medical information about the patient\'s condition and prognosis. This approach aims to find consensus based on the patient\'s presumed wishes and best interests. Option B disregards the son\'s concerns and the complexity of the situation. Option C removes the family from the decision-making process, which is generally not ideal when a surrogate decision-maker is needed. Option D defers medical decision-making to a legal process, which may be necessary later but is not the immediate first step in facilitating a medical discussion.', 1.00, '2026-05-21 15:18:20', '2026-05-21 15:18:20');
INSERT INTO latee.question (id, assessment_id, question, question_option, question_type, cognitive_level, explanation, points, created_at, updated_at) VALUES ('671bde1bfce547959c935193799d937a', '036954762944430699ca153fb1b0f87e', 'A 15-year-old female with a known history of complex migraines with aura presents to the ED with acute onset severe abdominal pain. She describes the pain as initially diffuse, now localized to the right lower quadrant, associated with nausea and one episode of non-bloody vomiting. She also reports experiencing a \'shimmering light\' in her peripheral vision just before the pain started, which she states is similar to her migraine aura, but the abdominal pain is atypical for her usual migraine presentation. Her vital signs are stable. Physical exam reveals moderate tenderness in the right lower quadrant with rebound. Labs show a WBC count of 13,000/µL. Despite her history of migraines with aura, what is the most appropriate *immediate* diagnostic step to evaluate her current presentation?', '[{"id": "A", "text": "Abdominal ultrasound.", "isCorrect": true}, {"id": "B", "text": "Administer sumatriptan and observe for migraine resolution.", "isCorrect": false}, {"id": "C", "text": "Consult Neurology for atypical migraine presentation.", "isCorrect": false}, {"id": "D", "text": "Order an urgent MRI of the brain to assess for new neurological pathology.", "isCorrect": false}]', 'MultipleChoice', 'Apply', 'The patient\'s presentation, including migratory pain, localized RLQ tenderness, nausea, and leukocytosis, is highly suggestive of acute appendicitis, despite her history of migraines and reported aura-like symptoms. While abdominal migraines exist, the localized tenderness and elevated WBC strongly point towards an acute surgical abdomen. An abdominal ultrasound is a reasonable initial imaging choice, especially in pediatric and female patients, to evaluate for appendicitis and other gynecological causes of RLQ pain, minimizing radiation exposure. Delaying investigation of the acute abdominal pain to treat for migraine or consult neurology would be a clinical pitfall, as appendicitis is a time-sensitive condition.', 1.00, '2026-05-21 16:09:08', '2026-05-21 16:09:08');
INSERT INTO latee.question (id, assessment_id, question, question_option, question_type, cognitive_level, explanation, points, created_at, updated_at) VALUES ('6d711819167b4248a64cabd7ee94aca2', '3173ad24bc344c0fbd1177f7e9ecb63d', 'A 19-year-old male is recently diagnosed with juvenile myoclonic epilepsy (JME) after experiencing a generalized tonic-clonic seizure. His EEG shows generalized 4-6 Hz polyspike-and-wave discharges. He is prescribed levetiracetam. He expresses concerns about medication side effects, asks if he can ever stop taking medication, and mentions he occasionally drinks alcohol with friends on weekends.', '[{"id": "A", "text": "Explain the chronic nature of JME and the importance of lifelong medication adherence for seizure control, discuss common side effects of levetiracetam and strategies to manage them, and strongly advise against alcohol consumption due to its seizure-provoking potential.", "isCorrect": true}, {"id": "B", "text": "Tell him that he might be able to stop medication in a few years if he remains seizure-free, and that moderate alcohol consumption is generally fine.", "isCorrect": false}, {"id": "C", "text": "Focus solely on the importance of taking his medication and dismiss his concerns about side effects as minor.", "isCorrect": false}, {"id": "D", "text": "Advise him to avoid alcohol completely and tell him that if he misses any doses, his seizures will definitely return.", "isCorrect": false}]', 'MultipleChoice', 'Apply', 'Option A is the most appropriate and comprehensive response. It educates the patient about the chronic nature of JME, which often requires lifelong treatment, and addresses his concerns about medication side effects with practical advice. Crucially, it provides clear and strong guidance against alcohol consumption, which is a known seizure trigger, especially in JME. Option B provides false hope regarding medication cessation and gives dangerous advice about alcohol. Option C is dismissive of valid patient concerns about side effects, which can impact adherence. Option D uses fear tactics and is overly deterministic, which can be counterproductive.', 1.00, '2026-05-21 15:18:20', '2026-05-21 15:18:20');
INSERT INTO latee.question (id, assessment_id, question, question_option, question_type, cognitive_level, explanation, points, created_at, updated_at) VALUES ('9673160b8d8b42e1a11e79c4f1596525', '3173ad24bc344c0fbd1177f7e9ecb63d', 'A 50-year-old female presents with new-onset focal aware seizures, characterized by a \'dÃ©jÃ  vu\' sensation followed by a brief period of unresponsiveness and lip-smacking. An EEG shows left temporal lobe discharges, and an MRI brain is normal. She is a long-haul truck driver and, after receiving her diagnosis, asks, \'Does this mean I can\'t drive my truck anymore? How will I support my family?\'', '[{"id": "A", "text": "Explain the legal requirements for driving with epilepsy in your jurisdiction, emphasizing the importance of seizure control for public safety, and discuss resources for vocational counseling or alternative employment options.", "isCorrect": true}, {"id": "B", "text": "Tell her that since her seizures are focal and she has an aura, she might be able to continue driving, but she should be cautious.", "isCorrect": false}, {"id": "C", "text": "Advise her to stop driving immediately and permanently, without further discussion of the legal framework or support.", "isCorrect": false}, {"id": "D", "text": "Suggest she try to drive for a few weeks to see if her medication controls the seizures before making a decision.", "isCorrect": false}]', 'MultipleChoice', 'Apply', 'Option A is the most appropriate response. It addresses her immediate concern about driving by explaining the legal and safety implications, which is crucial for a professional driver. It also demonstrates empathy for her financial concerns by offering to connect her with vocational resources. Option B is medically unsafe and legally irresponsible, as even focal seizures can impair driving ability. Option C is too abrupt and lacks support for the patient\'s significant life change. Option D is dangerous and irresponsible, as it puts the patient and public at risk.', 1.00, '2026-05-21 15:18:20', '2026-05-21 15:18:20');
INSERT INTO latee.question (id, assessment_id, question, question_option, question_type, cognitive_level, explanation, points, created_at, updated_at) VALUES ('9bb57879143842338af4512b4e5a076b', '3173ad24bc344c0fbd1177f7e9ecb63d', 'A 45-year-old female presents with chronic daily headaches for the past 6 months, unresponsive to multiple prophylactic medications including beta-blockers and tricyclic antidepressants. Her neurological exam is normal, and an MRI brain is unremarkable. During the consultation, she expresses frustration, stating, \'I feel like you think it\'s all in my head and there\'s nothing physically wrong with me.\'', '[{"id": "A", "text": "Acknowledge her frustration and validate her experience, explaining that chronic pain, including headache, involves complex changes in the brain\'s pain processing pathways, making it a real physical condition, and discuss a multidisciplinary approach.", "isCorrect": true}, {"id": "B", "text": "Reassure her that her MRI is normal, so there\'s no serious underlying brain disease, and suggest she try stress reduction techniques.", "isCorrect": false}, {"id": "C", "text": "Tell her that while the pain is real, psychological factors often play a significant role in chronic headache, and recommend a psychiatric evaluation.", "isCorrect": false}, {"id": "D", "text": "Explain that sometimes, despite extensive testing, we can\'t find a clear physical cause, and focus on managing symptoms.", "isCorrect": false}]', 'MultipleChoice', 'Apply', 'Option A is the most empathetic and therapeutically effective response. It validates her experience, directly addresses her concern about being dismissed, and provides a neurobiological explanation for chronic pain that legitimizes her symptoms as a \'real\' physical condition, even without a structural lesion. This approach builds trust and opens the door for a multidisciplinary treatment plan. Option B is dismissive of her pain, even if it reassures about serious disease. Option C can be perceived as blaming and stigmatizing, undermining trust. Option D is vague and may reinforce her feeling that her pain is not understood or taken seriously.', 1.00, '2026-05-21 15:18:20', '2026-05-21 15:18:20');
INSERT INTO latee.question (id, assessment_id, question, question_option, question_type, cognitive_level, explanation, points, created_at, updated_at) VALUES ('a87d4d8f528b4fd69f8c9aecb776ad33', '036954762944430699ca153fb1b0f87e', 'A 35-year-old female presents with a 12-hour history of acute, severe right lower quadrant abdominal pain, associated with nausea and vomiting. She also reports new-onset bilateral lower extremity weakness and paresthesias, which began shortly after the abdominal pain. Her vital signs are stable. On physical examination, she has significant tenderness and guarding in the right lower quadrant. Neurological examination reveals symmetric 3/5 weakness in hip flexion and knee extension bilaterally, with diminished patellar reflexes. Her WBC count is 11,000/µL. Given the co-occurrence of acute abdominal pain suggestive of appendicitis and new neurological deficits, what is the most appropriate *initial* diagnostic approach?', '[{"id": "A", "text": "Urgent abdominal CT scan.", "isCorrect": true}, {"id": "B", "text": "Lumbar puncture to evaluate for Guillain-Barré Syndrome.", "isCorrect": false}, {"id": "C", "text": "MRI of the thoracic and lumbar spine.", "isCorrect": false}, {"id": "D", "text": "Electromyography (EMG) and nerve conduction studies.", "isCorrect": false}]', 'MultipleChoice', 'Apply', 'The patient presents with classic signs and symptoms of acute appendicitis (RLQ pain, nausea, vomiting, tenderness, guarding, mild leukocytosis). While the new-onset bilateral lower extremity weakness and paresthesias are concerning for an acute neurological condition (e.g., Guillain-Barré Syndrome, transverse myelitis), acute appendicitis is a time-sensitive surgical emergency that can lead to perforation and sepsis if not diagnosed and treated promptly. Therefore, the most prudent *initial* diagnostic approach is to rule out the acute surgical abdomen with an urgent abdominal CT scan. Once appendicitis is addressed or ruled out, a comprehensive neurological workup (including lumbar puncture, MRI spine, EMG) can proceed. Delaying the appendicitis workup for neurological investigations could lead to severe complications. This approach prioritizes the most immediately life-threatening condition.', 1.00, '2026-05-21 16:09:08', '2026-05-21 16:09:08');
INSERT INTO latee.question (id, assessment_id, question, question_option, question_type, cognitive_level, explanation, points, created_at, updated_at) VALUES ('bf2ad8a8b2384e29800ff1da4eae20c4', '3173ad24bc344c0fbd1177f7e9ecb63d', 'A 68-year-old male presents to the emergency department with acute onset right-sided weakness and expressive aphasia. His vital signs are stable (BP 140/85 mmHg, HR 78 bpm, RR 16 bpm, Temp 37.0Â°C). A non-contrast CT head rules out hemorrhage, and he receives intravenous thrombolysis within 3 hours of symptom onset. Post-thrombolysis, he remains stable but has residual right hemiparesis (MRC 3/5) and significant expressive aphasia. His anxious family asks, \'Will he ever be able to talk and move his arm normally again?\'', '[{"id": "A", "text": "Tell the family that it\'s too early to tell definitively, but with intensive rehabilitation, significant improvement is possible, and you will connect them with the rehabilitation team.", "isCorrect": true}, {"id": "B", "text": "Assure the family that most patients recover fully after a stroke, especially with early treatment like thrombolysis.", "isCorrect": false}, {"id": "C", "text": "Explain that given his age and the severity of his initial symptoms, complete recovery is unlikely, and they should prepare for long-term disability.", "isCorrect": false}, {"id": "D", "text": "Suggest they research stroke recovery statistics online to get a better understanding of his prognosis.", "isCorrect": false}]', 'MultipleChoice', 'Apply', 'Option A is the most appropriate response. It acknowledges the uncertainty of early prognosis while offering hope and emphasizing the role of rehabilitation. It also commits to connecting them with the relevant specialists, demonstrating a collaborative approach to care. Option B provides false reassurance and sets unrealistic expectations. Option C is overly pessimistic and can be demoralizing without sufficient information or time. Option D is dismissive and shifts responsibility to the family, which is inappropriate for patient-centered care.', 1.00, '2026-05-21 15:18:20', '2026-05-21 15:18:20');
INSERT INTO latee.question (id, assessment_id, question, question_option, question_type, cognitive_level, explanation, points, created_at, updated_at) VALUES ('c8edcea933c749e8aa204e094cb16a04', '036954762944430699ca153fb1b0f87e', 'A 78-year-old male with a history of mild cognitive impairment is brought to the ED by his family due to 3 days of progressive lethargy, confusion, and worsening abdominal pain. He is febrile (39.2°C), hypotensive (BP 85/50 mmHg), and tachycardic (HR 115 bpm). His abdomen is distended and diffusely tender with guarding, most pronounced in the right lower quadrant. Labs reveal a WBC count of 22,000/µL, lactate 4.5 mmol/L, and acute kidney injury. A rapid bedside neurological assessment shows generalized weakness and disorientation, but no focal deficits. A non-contrast head CT performed due to altered mental status is unremarkable. Considering the patient\'s overall clinical picture, what is the most likely *primary* underlying cause of his acute neurological deterioration and systemic instability?', '[{"id": "A", "text": "Perforated appendicitis with septic encephalopathy.", "isCorrect": true}, {"id": "B", "text": "Acute ischemic stroke.", "isCorrect": false}, {"id": "C", "text": "Delirium secondary to urinary tract infection.", "isCorrect": false}, {"id": "D", "text": "Wernicke\'s encephalopathy due to nutritional deficiency.", "isCorrect": false}]', 'MultipleChoice', 'Apply', 'The patient presents with clear signs of severe sepsis and septic shock (fever, hypotension, tachycardia, elevated lactate, acute kidney injury) originating from an acute abdominal process (distended, diffusely tender abdomen with guarding, pronounced RLQ tenderness, high WBC). The neurological deterioration (lethargy, confusion, disorientation) is consistent with septic encephalopathy, a common complication of severe systemic infection. Given the RLQ tenderness and progressive abdominal pain, perforated appendicitis is the most likely primary source of sepsis. Acute stroke is ruled out by the normal head CT and lack of focal deficits. While delirium from other infections (like UTI) is possible, the severe abdominal findings make a primary abdominal source more probable. Wernicke\'s encephalopathy is less likely given the acute presentation and lack of specific risk factors. The management of septic encephalopathy involves treating the underlying sepsis, which in this case is likely from perforated appendicitis.', 1.00, '2026-05-21 16:09:08', '2026-05-21 16:09:08');
INSERT INTO latee.question (id, assessment_id, question, question_option, question_type, cognitive_level, explanation, points, created_at, updated_at) VALUES ('ff457a733f88416a8b9ba8b39fd854c1', '036954762944430699ca153fb1b0f87e', 'A 19-year-old male presents to the emergency department with a 24-hour history of periumbilical pain that has migrated to the right lower quadrant. He reports nausea, anorexia, and a low-grade fever (38.1°C). His vital signs are stable (BP 120/70 mmHg, HR 88 bpm, RR 16 bpm, SpO2 99% on room air). On examination, he has localized tenderness and guarding in the right lower quadrant. His white blood cell count is 14,500/µL with neutrophilia. Additionally, he reports feeling \'a bit foggy\' and has difficulty concentrating, which he attributes to the pain and lack of sleep. Neurological exam is otherwise non-focal. Given the clinical presentation, what is the most appropriate *initial* diagnostic imaging study to confirm or rule out appendicitis, while also considering the patient\'s mild cognitive symptoms?', '[{"id": "A", "text": "Abdominal and pelvic CT scan with intravenous contrast.", "isCorrect": true}, {"id": "B", "text": "MRI of the brain to investigate the \'foggy\' sensation.", "isCorrect": false}, {"id": "C", "text": "Lumbar puncture to rule out meningitis.", "isCorrect": false}, {"id": "D", "text": "Electroencephalogram (EEG) to assess for seizure activity.", "isCorrect": false}]', 'MultipleChoice', 'Apply', 'The patient presents with classic symptoms and signs of acute appendicitis (migratory pain, RLQ tenderness, fever, leukocytosis). An abdominal and pelvic CT scan with intravenous contrast is the gold standard imaging modality for diagnosing appendicitis, offering high sensitivity and specificity, and can also identify alternative causes of abdominal pain. While the patient reports feeling \'foggy,\' this is a non-specific symptom that can be attributed to systemic illness, pain, or dehydration, and does not warrant immediate advanced neurological imaging in the context of clear signs of an acute surgical abdomen. Prioritizing the potentially life-threatening abdominal pathology is crucial. MRI brain, lumbar puncture, and EEG are not indicated as initial steps given the primary abdominal presentation and lack of specific neurological signs.', 1.00, '2026-05-21 16:09:08', '2026-05-21 16:09:08');
