INSERT INTO latee.roadmaps (id, learner_id, content, version, created_at) VALUES ('3bc8616da15745cd9d75ae9f28778954', 'USR-LRN-01', '{"goal": "To build a systematic, stepwise approach linking high-quality history taking directly to an accurate abdominal diagnosis and management plan.", "roadmap": [{"order_id": 1, "detailed_explain": "Accurate diagnosis starts with understanding pain generation. Visceral (dull, midline), parietal (sharp, localized), and referred pain patterns directly correlate to underlying pathology. This explains symptom evolution, preventing reliance on memorization alone. Study by mapping each abdominal organ\'s embryonic innervation to its pain referral pattern and trajectory.", "amount_of_time_days": 1, "recommended_content": "Pain Pathophysiology: Linking Mechanism to Presentation"}, {"order_id": 2, "detailed_explain": "Transform history taking from a checklist to a dynamic diagnostic tool. For each presenting complaint, consciously generate a top differential early using SOCRATES and associated symptoms, then actively seek discriminating factors (e.g., relation to meals, stool changes). Practice with virtual case simulators, forcing a provisional diagnosis after each history section.", "amount_of_time_days": 2, "recommended_content": "Structured History: Embedding a Diagnostic Hypothesis"}, {"order_id": 3, "detailed_explain": "Bridge history and physical exam findings with targeted diagnostics. A positive psoas sign refines a vague history towards retrocecal appendicitis. Actively calculate Alvarado or Ranson scores in real-time to make findings objective, sharpening your ability to justify a specific diagnosis. Practice by reading vignettes, predicting the score, then seeing the outcome.", "amount_of_time_days": 2, "recommended_content": "Clinical Decision Integration: Exam, Labs & Scoring"}, {"order_id": 4, "detailed_explain": "The ultimate goal is to safely decide a management path. Focus on synthesis: integrate history, exam, and lactate/imaging to identify mesenteric ischemia versus adynamic ileus, or a non-operative pneumonia from a perforated ulcer. This prevents fixation error. Use published clinical algorithms (for appendicitis, pancreatitis) as a roadmap for your own thought process.", "amount_of_time_days": 2, "recommended_content": "The Diagnostic Pivot: Surgical vs. Medical Management"}], "total_days": 7, "roadmap_title": "Targeted Abdominal Diagnosis: From History to Decision"}', '1', '2026-05-21 16:45:00');
